window.SIMDRON_QUIZ_BANK = [{"id":"q001","doc":"simdron","topic":"Control HID","level":4,"question":"Un operador utiliza Mode 2. ¿Qué asignación permite conservar el esquema habitual de ejes?","options":["Stick izquierdo: throttle/yaw; derecho: pitch/roll","Stick izquierdo: pitch/roll; derecho: throttle/yaw","Stick izquierdo: throttle/roll; derecho: pitch/yaw","Stick izquierdo: pitch/yaw; derecho: throttle/roll"],"answer":0,"why":"En Mode 2, el stick izquierdo controla throttle y yaw; el derecho controla pitch y roll.","page":45,"link":"simdron/gamepad-hid.html"},{"id":"q002","doc":"simdron","topic":"Preparación","level":3,"question":"El gamepad no aparece correctamente al iniciar SimDron. ¿Qué orden recomienda el manual?","options":["Iniciar SimDron y activar Bluetooth después","Conectar el gamepad por Bluetooth antes de iniciar la aplicación","Esperar hasta la escena de vuelo para emparejarlo","Cambiar de escena antes de emparejarlo"],"answer":1,"why":"El manual advierte expresamente que el gamepad debe estar conectado por Bluetooth antes de iniciar la aplicación.","page":46,"link":"simdron/configurar-hid.html"},{"id":"q003","doc":"simdron","topic":"Control HID","level":4,"question":"Querés reasignar una acción del gamepad sin cambiar el dispositivo. ¿Qué capacidad describe el panel HID?","options":["Elegir uno de 16 ejes por acción","Elegir únicamente entre dos perfiles fijos","Asignar una acción solo a gatillos","Reprogramar el firmware del control"],"answer":0,"why":"Cada acción admite seleccionar uno de 16 ejes mediante menús desplegables.","page":49,"link":"simdron/configurar-hid.html"},{"id":"q004","doc":"simdron","topic":"Control HID","level":3,"question":"Un alumno quiere alternar entre ajustes de control guardados. ¿Cuántos perfiles admite el selector descrito en el manual?","options":["2","3","4","8"],"answer":2,"why":"El menú Template permite guardar hasta cuatro perfiles de configuración.","page":51,"link":"simdron/configurar-hid.html"},{"id":"q005","doc":"simdron","topic":"Modos de vuelo","level":4,"question":"¿Qué caracteriza específicamente al modo HORIZON según el manual?","options":["Throttle es empuje directo sin control de altura","Mantiene la altura como prioridad mediante estabilización","Elimina el control de yaw","Permite rotación libre ilimitada"],"answer":1,"why":"HORIZON prioriza mantener la altura y utiliza throttle como control de altitud.","page":55,"link":"simdron/modos-vuelo.html"},{"id":"q006","doc":"simdron","topic":"Modos de vuelo","level":5,"question":"En ANGLE, el alumno inclina el dron hacia adelante. ¿Por qué la altitud puede variar aunque conserve autoestabilización?","options":["Porque el yaw reemplaza al throttle","Porque el ángulo de inclinación modifica la componente vertical del empuje","Porque ANGLE obliga a usar seguimiento de terreno","Porque desactiva todos los límites de ángulo"],"answer":1,"why":"En ANGLE el throttle se aplica como fuerza de empuje y la inclinación cambia su componente vertical; el ángulo máximo está limitado.","page":56,"link":"simdron/modos-vuelo.html"},{"id":"q007","doc":"simdron","topic":"Modos de vuelo","level":4,"question":"¿Cuál de estas afirmaciones describe correctamente ACRO?","options":["Mantiene el horizonte nivelado por PID","Tiene un límite de inclinación fijo","Permite rotación libre en los tres ejes sin autoestabilización","Mantiene altura aunque se invierta el dron"],"answer":2,"why":"ACRO no autoestabiliza ni limita el ángulo; el piloto debe administrar empuje y orientación.","page":57,"link":"simdron/modos-vuelo.html"},{"id":"q008","doc":"simdron","topic":"Modos de vuelo","level":5,"question":"Dos alumnos aplican el mismo valor de throttle. Uno usa HORIZON y otro ANGLE. ¿Qué diferencia fundamental hay?","options":["En HORIZON controla altura; en ANGLE representa empuje","En ambos modos siempre ordena una altitud exacta","En ANGLE controla únicamente yaw","En HORIZON controla el FOV"],"answer":0,"why":"El manual diferencia claramente el control de altitud de HORIZON del empuje de ANGLE.","page":55,"link":"simdron/modos-vuelo.html"},{"id":"q009","doc":"simdron","topic":"HUD / OSD","level":4,"question":"La aeronave sobrevuela una estructura alta. ¿Qué medición corresponde a la distancia vertical obtenida mediante un sensor hasta el objeto o terreno inferior?","options":["MSL","AGL","FOV","FPS"],"answer":1,"why":"AGL se obtiene mediante un rayo sensor hasta una colisión o el terreno; MSL utiliza la referencia de altitud de mundo.","page":103,"link":"simdron/osd.html"},{"id":"q010","doc":"simdron","topic":"HUD / OSD","level":4,"question":"¿Cuál es la diferencia más precisa entre MSL y AGL en el HUD del manual?","options":["MSL refiere a un origen vertical del mundo; AGL mide hasta la superficie inferior","MSL muestra la distancia al piloto; AGL la distancia al instructor","MSL es velocidad; AGL es rumbo","Son dos unidades intercambiables para el mismo dato"],"answer":0,"why":"El documento define MSL desde el origen Y de mundo y AGL por detección de superficie con colisión.","page":103,"link":"simdron/osd.html"},{"id":"q011","doc":"simdron","topic":"HUD / OSD","level":3,"question":"El indicador FPS baja de 72 a 60. ¿Cómo lo interpreta el manual?","options":["72 es lo ideal y puede descender a 60","60 es siempre el máximo permitido","FPS mide la radiofrecuencia, no el rendimiento visual","72 corresponde al número de satélites"],"answer":0,"why":"En el esquema de OSD se indica que el rendimiento ideal son 72 FPS, aunque puede descender a 60.","page":102,"link":"simdron/osd.html"},{"id":"q012","doc":"simdron","topic":"Configuración gráfica","level":3,"question":"¿Qué diferencia al perfil Custom frente a los perfiles gráficos predefinidos?","options":["Impide ajustar sombras y vegetación","Permite ajuste manual de parámetros específicos","Bloquea el cambio de nivel de detalle","Solo sirve para transmitir video"],"answer":1,"why":"Custom permite ajustar parámetros visuales en vez de aplicar únicamente un preset automático.","page":38,"link":"simdron/manual-y-calidad.html"},{"id":"q013","doc":"simdron","topic":"Física","level":4,"question":"Querés reducir lo brusco de los giros sin modificar directamente la masa. ¿Qué parámetro corresponde revisar?","options":["Angular Drag","FOV","MSL","RF Link"],"answer":0,"why":"Angular Drag controla la resistencia al giro; Drag lineal frena el desplazamiento.","page":118,"link":"simdron/fisicas-presets.html"},{"id":"q014","doc":"simdron","topic":"Física","level":5,"question":"¿Qué efecto tiene aumentar la inercia de entrada (input spool) según la documentación?","options":["Hace las órdenes más instantáneas","Suaviza los cambios y produce una respuesta más progresiva","Duplica el número de hélices","Desactiva el controlador PID"],"answer":1,"why":"La inercia de entrada suaviza las órdenes; 0 ms implica respuesta instantánea y más nerviosa.","page":118,"link":"simdron/fisicas-presets.html"},{"id":"q015","doc":"simdron","topic":"Física","level":4,"question":"¿Qué describe Drag en el panel de sensación de vuelo?","options":["Resistencia al movimiento lineal","Cantidad de datos enviados por radio","Altura de referencia de mundo","Velocidad del zoom"],"answer":0,"why":"Drag se refiere al frenado lineal del dron; Angular Drag al frenado de su rotación.","page":118,"link":"simdron/fisicas-presets.html"},{"id":"q016","doc":"simdron","topic":"Interacciones VR","level":3,"question":"En la escena de montaje, ¿qué combinación de interacciones se usa para manipular objetos y operar paneles?","options":["Grab para objetos; poke/ray para paneles","Solo teclado USB para todo","Joystick derecho para ensamblar todas las piezas","Exclusivamente el panel de Mission Control"],"answer":0,"why":"La escena utiliza hand tracking con grab y controles poke/ray para paneles y botones.","page":64,"link":"simdron/adaptacion-montaje.html"},{"id":"q017","doc":"simdron","topic":"Meta Quest","level":3,"question":"¿Cómo describe el manual el cambio entre vista inmersiva y passthrough?","options":["Solo al reiniciar el dispositivo","Mediante botón de acción o doble toque ligero en el visor","Desconectando el Wi-Fi","Cambiando manualmente el perfil de dron"],"answer":1,"why":"Se mencionan el botón de acción y dos golpes leves en la sujeción lateral del visor.","page":29,"link":"simdron/sistema-operativo.html"},{"id":"q018","doc":"simdron","topic":"Reportes","level":3,"question":"¿Qué tipo de archivo utiliza FlightLogs para registrar resultados de vuelo?","options":["CSV","GLB","APK","FBX"],"answer":0,"why":"El manual describe FlightLogs como archivos CSV con datos de vuelo.","page":33,"link":"simdron/cuenta-chat-casting.html"},{"id":"q019","doc":"simdron","topic":"Entrenamiento","level":4,"question":"¿Cómo se distribuye la planificación básica de 30 horas?","options":["Tres semanas de cinco días y dos horas por día","Diez días de tres horas todos los días","Una semana de seis horas diarias","Tres jornadas de diez horas"],"answer":0,"why":"El plan propone tres semanas, cinco días por semana, dos horas diarias y dos módulos de una hora.","page":176,"link":"simdron/plan-30-horas.html"},{"id":"q020","doc":"simdron","topic":"Controles adicionales","level":4,"question":"El usuario está perdido en un escenario y utiliza el teclado Bluetooth. ¿Qué tecla vuelve a la escena principal?","options":["N","B","L","F"],"answer":2,"why":"La tecla L vuelve a la escena principal, según la tabla de interacciones por teclado.","page":96,"link":"simdron/teclado-durante.html"},{"id":"q021","doc":"simdron","topic":"Controles adicionales","level":4,"question":"Una interfaz movida temporalmente pierde interacción. ¿Qué tecla indica el manual para reiniciar la pantalla del control?","options":["B","L","N","P"],"answer":0,"why":"B reinicia la pantalla del control; L regresa a la escena principal y P reinicia la escena.","page":96,"link":"simdron/teclado-durante.html"},{"id":"q022","doc":"simdron","topic":"Fotografía","level":3,"question":"Para extraer los registros y capturas generados por SimDron, ¿qué conexión describe el manual?","options":["USB-C del Quest a una PC","HDMI directo desde el visor","Cable Ethernet en el mando","Solo impresión desde C2"],"answer":0,"why":"Se indica conectar Meta Quest a una PC por USB-C para acceder a los archivos almacenados.","page":33,"link":"simdron/cuenta-chat-casting.html"},{"id":"q023","doc":"simdron","topic":"Gates","level":4,"question":"En el panel Gates, ¿qué hace Distributor?","options":["Redistribuye portales por todo el terreno","Exporta un archivo CSV","Cambia el tipo de cámara","Resetea la batería virtual"],"answer":0,"why":"Distributor redistribuye los portales; Path Gen genera una ruta sugerida.","page":155,"link":"simdron/gates.html"},{"id":"q024","doc":"simdron","topic":"Gates","level":4,"question":"En Gates, ¿qué acción corresponde a Path Gen?","options":["Generar un camino sugerido de entrenamiento","Establecer las coordenadas del alumno","Asignar una estación Qxx","Cambiar el mapa a ortofoto"],"answer":0,"why":"Path Gen genera la ruta sugerida para un recorrido desafiante y puede apagarse volviendo a pulsarlo.","page":155,"link":"simdron/gates.html"},{"id":"q025","doc":"simdron","topic":"Licenciamiento","level":4,"question":"¿Qué dos referencias distingue el manual para el licenciamiento de SimDron?","options":["Usuario y dispositivo","Solo IP y router","Solo correo del docente y resolución","Fecha y número de escenario"],"answer":0,"why":"El manual diferencia la cuenta de Meta del usuario y el fingerprint del dispositivo.","page":62,"link":"simdron/primer-inicio.html"},{"id":"q026","doc":"simdron","topic":"Control HID","level":4,"question":"¿Qué control realiza un ajuste fino que resulta especialmente útil cuando el eje es analógico?","options":["Sliders de sensibilidad/zonas del panel HID","Selector de misiones de C2","Pantalla de telemetría del instructor","Generador de calcos"],"answer":0,"why":"El manual describe sliders de ajuste fino para ejes, aprovechables especialmente en ejes analógicos.","page":50,"link":"simdron/configurar-hid.html"},{"id":"q027","doc":"mission-control","topic":"Topología","level":4,"question":"Para reducir latencia entre el Hub docente y el router del aula, ¿qué conexión se recomienda?","options":["Ethernet por cable","Bluetooth directo","USB-C entre los visores","Compartir Internet desde cada Quest"],"answer":0,"why":"El manual recomienda conectar el router Wi-Fi al Hub docente mediante cable de red.","page":5,"link":"mission-control/topologia.html"},{"id":"q028","doc":"mission-control","topic":"Arquitectura","level":4,"question":"¿Qué sucede si se cierra la ventana del navegador donde se usa Mission Control?","options":["El servicio puede continuar ejecutándose en Windows","Todos los datos del aula se borran siempre","Todas las Quest se formatean","Se apaga físicamente el router"],"answer":0,"why":"Mission Control se ejecuta como servicio y el frontend se abre en navegador; cerrar la ventana no equivale a finalizar el ejercicio.","page":6,"link":"mission-control/instalacion.html"},{"id":"q029","doc":"mission-control","topic":"Cartografía","level":5,"question":"El instructor carga una ortofoto GIS en Mission Control. ¿Qué limitación aclara expresamente el manual?","options":["La capa cartográfica no se proyecta automáticamente sobre el terrain del Quest","La ortofoto reemplaza el terreno físico del Quest","Solo admite imágenes capturadas con el Quest","Obliga a activar Internet durante cada clase"],"answer":0,"why":"Las capas GIS se usan como fondo contextual de Mission Control; no se proyectan automáticamente en el terreno 3D de SimDron.","page":13,"link":"mission-control/cartografia.html"},{"id":"q030","doc":"mission-control","topic":"Cartografía","level":4,"question":"Querés trabajar en un aula sin salida a Internet con cartografía ya instalada. ¿Qué opción se describe?","options":["Solo offline / ahorro de datos","Forzar streaming remoto","Borrar paquetes locales","Desactivar el Hub"],"answer":0,"why":"La opción solo offline evita descargas y emplea recursos cartográficos locales.","page":13,"link":"mission-control/cartografia.html"},{"id":"q031","doc":"mission-control","topic":"Organización","level":3,"question":"¿Qué área de Mission Control permite guardar configuraciones de ejercicios para reutilizarlas después?","options":["Clases","C2 Wall","VFX","QA Aula"],"answer":0,"why":"Clases almacena planificaciones localmente para repetir ejercicios sin reconstruirlos.","page":31,"link":"mission-control/clases.html"},{"id":"q032","doc":"mission-control","topic":"Operación del aula","level":4,"question":"Antes de aplicar una acción a un alumno concreto, ¿qué selección reduce el riesgo de afectar a todo el curso?","options":["Elegir la estación Qxx correspondiente y no TODOS","Cambiar el color del mapa","Salir del modo claro","Cerrar la vista C2"],"answer":0,"why":"AULA sirve para delimitar contexto. La diferencia entre Q03 y TODOS se menciona para evitar órdenes con alcance equivocado.","page":12,"link":"mission-control/aula.html"},{"id":"q033","doc":"mission-control","topic":"Dron Lab","level":5,"question":"Un instructor aplica un preset de física remoto y luego el alumno selecciona otro preset desde Quest. ¿Qué prioridad describe el manual?","options":["El cambio local vuelve a tener prioridad hasta otro envío remoto","El preset remoto bloquea permanentemente el Quest","Se eliminan ambos presets","Se reinicia Mission Control automáticamente"],"answer":0,"why":"El preset remoto no sobrescribe permanentemente las preferencias; un cambio local posterior prima hasta recibir una nueva revisión remota.","page":38,"link":"mission-control/dronlab.html"},{"id":"q034","doc":"mission-control","topic":"Auto/AI","level":4,"question":"¿Qué modo autónomo utiliza los waypoints previamente definidos en TÁCTICO?","options":["WAYPOINT ROUTE","EXPO","VFX","OFF"],"answer":0,"why":"WAYPOINT ROUTE consume los waypoints creados en el módulo TÁCTICO.","page":39,"link":"mission-control/auto-ai.html"},{"id":"q035","doc":"mission-control","topic":"Dispositivos","level":4,"question":"Una Quest recién conectada aparece como UNASSIGNED. ¿Cuál es la operación prevista?","options":["Asignarle una estación Q01–Q10","Cambiarla obligatoriamente por otra","Eliminar todos los datos de telemetría","Conectarla por HDMI"],"answer":0,"why":"Desde Dispositivos el instructor puede identificar y asignar una estación Qxx a una Quest nueva.","page":43,"link":"mission-control/dispositivos.html"},{"id":"q036","doc":"mission-control","topic":"Datos de vuelo","level":4,"question":"¿Qué formato permite incorporar datos de un ejercicio individual anterior al mapa de Mission Control?","options":["CSV","OBJ","WAV","HDR"],"answer":0,"why":"Además del seguimiento en vivo, Mission Control puede cargar archivos CSV de vuelos anteriores.","page":50,"link":"mission-control/config-mapas.html"},{"id":"q037","doc":"mission-control","topic":"Vista C2","level":4,"question":"¿Cuál es la diferencia entre las vistas C2 Mixto y Foco?","options":["Mixto combina mapa y cámaras; Foco se concentra en un alumno y su dron SRR","Mixto borra la telemetría; Foco apaga el Hub","Mixto solo sirve sin Quest; Foco exige Internet","Son modos idénticos de impresión"],"answer":0,"why":"Mixto visualiza mapa y cámaras principales; Foco concentra el mapa y las vistas del dron principal y SRR de una Quest.","page":55,"link":"mission-control/c2.html"},{"id":"q038","doc":"mission-control","topic":"Vista C2","level":5,"question":"¿Por qué C2 Wall evita actualizar las diez cámaras a 72 FPS?","options":["Para reducir la carga de streaming y preservar la fluidez de los Quest","Porque los Quest solo funcionan a 3 FPS","Porque solo muestra fotografías estáticas","Para mejorar el GPS del simulador"],"answer":0,"why":"El manual indica una actualización aproximada de 3 imágenes por segundo para Wall, priorizando la experiencia del alumno en Quest.","page":56,"link":"mission-control/c2.html"},{"id":"q039","doc":"mission-control","topic":"Tablet","level":4,"question":"En el modo de asistencia al alumno de Tablet, ¿qué alternativa permite obtener una imagen estable en vez de la vista Live?","options":["Modo captura","Modo MGRS","Modo Prowl","Modo Dron Lab"],"answer":0,"why":"Tablet ofrece Live, descrito a unos 8 FPS, y un modo de captura para congelar una imagen estable.","page":58,"link":"mission-control/tablet.html"},{"id":"q040","doc":"mission-control","topic":"C2 / VFX","level":4,"question":"El instructor cambia a White Hot desde C2. ¿Qué alcance tiene ese ajuste según el manual?","options":["Afecta la visualización en C2, no sustituye automáticamente la configuración visual de Quest","Reemplaza el firmware de los Quest","Cambia la vegetación del terrain en todos los Quest","Modifica el PID del dron"],"answer":0,"why":"Los ajustes de brillo, contraste y visualización VIS/térmica descritos en VFX afectan C2; cada Quest mantiene su configuración.","page":57,"link":"mission-control/vfx-c2.html"},{"id":"q041","doc":"mission-control","topic":"QA Aula","level":4,"question":"¿Por qué QA Aula está separado de la vista de uso normal del docente?","options":["Para concentrar diagnósticos y no saturar la interfaz operativa","Porque no funciona sin Internet","Porque solo admite controles de vuelo","Porque elimina registros de ejercicios"],"answer":0,"why":"El manual separa diagnóstico y soporte técnico para evitar advertencias innecesarias durante una clase.","page":44,"link":"mission-control/qa-aula.html"},{"id":"q042","doc":"mission-control","topic":"Misiones","level":3,"question":"¿Qué produce el generador de Misiones además de las capas de planificación?","options":["Briefing y debriefing imprimibles","Una APK nueva","Los archivos fuente de Unity","El instalador del Hub"],"answer":0,"why":"El generador prepara briefing y debriefing en pestañas, con posibilidad de imprimirlos.","page":52,"link":"mission-control/misiones.html"},{"id":"q043","doc":"mission-control","topic":"Calcos","level":4,"question":"¿Qué distingue Calcos del módulo TÁCTICO?","options":["Calcos permite dibujo libre sobre el mapa; TÁCTICO contiene información estructurada","Calcos administra licencias de Quest","Calcos sirve solo para configurar el gamepad","TÁCTICO se usa exclusivamente para cambiar resolución"],"answer":0,"why":"Calcos crea anotaciones y geometrías libres, mientras que TÁCTICO organiza símbolos, puntos y rutas.","page":18,"link":"mission-control/calcos.html"},{"doc":"simdron","page":114,"level":5,"topic":"Inicialización","question":"Si el pad de despegue quedó lejos del usuario, ¿qué control lo aproxima?","options":["Origin H","Cube","Respawn","MENU Return"],"answer":0,"why":"Origin H devuelve el pad de inicio frente al usuario.","id":"q044","link":"simdron/init-loadout.html"},{"doc":"simdron","page":128,"level":5,"topic":"Enlaces","question":"¿Qué sucede cuando el filamento simulado FO se agota?","options":["Se corta la transmisión y se pierde el control","Se conmuta automáticamente a RF","Solo desaparece la traza visual del cable","El dron sigue por inercia con control normal"],"answer":0,"why":"El manual indica pérdida del enlace al llegar a cero el recorrido de fibra.","id":"q045","link":"simdron/hardware.html"},{"doc":"simdron","page":134,"level":5,"topic":"Viento","question":"Si el viento supera la velocidad del dron en el sentido contrario, ¿qué puede pasar?","options":["Que deje de avanzar respecto al terreno","Que avance más lento pero sin poder detenerse","Que el efecto solo se note en la cámara","Que el viento se compense elevando FOV"],"answer":0,"why":"El manual explica que una combinación adversa puede anular avance efectivo.","id":"q046","link":"simdron/wind.html"},{"doc":"simdron","page":137,"level":5,"topic":"Payload","question":"Si aumenta la masa de la carga suspendida, ¿qué efecto espera el manual?","options":["Respuesta más lenta y mayor influencia pendular","Respuesta más rápida y menor oscilación de la carga","Solo más arrastre visual sin efecto físico","Menor momento pendular al acelerar"],"answer":0,"why":"El panel advierte más lentitud y tirones con masa adicional.","id":"q047","link":"simdron/payload.html"},{"doc":"simdron","page":59,"level":4,"topic":"Modelos de dron","question":"¿Qué perfil está concebido para transición de despegue vertical a vuelo rápido casi horizontal?","options":["High Speed","SRR","RTF","Mini"],"answer":0,"why":"El texto del High Speed explica despegue vertical y posterior avance casi horizontal.","id":"q048","link":"simdron/modelos-pid.html"},{"doc":"simdron","page":104,"level":4,"topic":"OSD","question":"¿Por qué el OSD muestra batería de sistema y batería de motores por separado?","options":["Representan subsistemas con consumo y autonomía propios","Una es la batería del teclado de instructor","Una siempre refleja la carga de la tablet externa","Son duplicados visuales sin función"],"answer":0,"why":"El manual distingue alimentación de cámara/control y la destinada a motores.","id":"q049","link":"simdron/osd.html"},{"doc":"simdron","page":50,"level":5,"topic":"Configuración HID","question":"¿Qué control ajusta el umbral o valor por defecto del recorrido de un eje?","options":["Trimming","Dead Zone","Sensitivity","Invert"],"answer":0,"why":"Trimming cambia el umbral/rango y el valor por defecto del eje.","id":"q050","link":"simdron/configurar-hid.html"},{"doc":"simdron","page":57,"level":5,"topic":"Modos de vuelo","question":"Para practicar inversión de actitud y rotaciones sin límites automáticos, ¿qué modo corresponde?","options":["ACRO","ANGLE","HORIZON","RTH"],"answer":0,"why":"ACRO permite control sin autoestabilización ni límite angular.","id":"q051","link":"simdron/modos-vuelo.html"},{"doc":"simdron","page":60,"level":5,"topic":"Control PID","question":"Ante rebotes tras corregir la actitud, ¿qué componente del PID se ajusta para amortiguarlos?","options":["D","P proporcional","I integral","Max Angle"],"answer":0,"why":"La guía de PID explica que D ayuda a amortiguar y reducir sobreoscilaciones.","id":"q052","link":"simdron/modelos-pid.html"},{"doc":"simdron","page":70,"level":5,"topic":"Colisiones y vegetación","question":"¿Qué parte de la vegetación detiene con mayor probabilidad al dron?","options":["Las zonas rígidas como troncos o centros del árbol","Las puntas de hojas y ramas flexibles","Todas las hojas sin distinción","Solo la sombra proyectada sobre el suelo"],"answer":0,"why":"La vegetación implementa colisiones principalmente en partes duras; extremos blandos pueden carecer de hitbox.","id":"q053","link":"simdron/catalogo-escenarios.html"},{"doc":"simdron","page":95,"level":5,"topic":"SRR","question":"¿Qué precisión alternativa ofrece el panel de coordenadas del SRR?","options":["Seis u ocho dígitos","Cuatro u ocho dígitos","Ocho o diez dígitos","Solo diez dígitos"],"answer":0,"why":"El HUD permite alternar coordenadas de seis u ocho dígitos.","id":"q054","link":"simdron/srr.html"},{"doc":"simdron","page":102,"level":5,"topic":"OSD","question":"¿Cuáles son las tres modalidades de enlace señaladas en el OSD?","options":["SAT, RF y FO","SAT, RF y Wi-Fi","RF, FO y Bluetooth","SAT, HDMI y RF"],"answer":0,"why":"El OSD diferencia señales satelital, radiofrecuencia y fibra óptica.","id":"q055","link":"simdron/osd.html"},{"doc":"simdron","page":107,"level":5,"topic":"ECM","question":"Según el esquema del filtro analógico, ¿qué región representa pérdida de control del dron?","options":["Blanca","Violeta","Turquesa","Verde"],"answer":0,"why":"El esquema distingue interferencia intermitente, blackout de video y pérdida de mando.","id":"q056","link":"simdron/capas-senal.html"},{"doc":"simdron","page":110,"level":5,"topic":"Visión térmica","question":"¿Sobre qué elementos se aplica el efecto térmico procedural descrito?","options":["Objetos del entorno y entidades, no todo el terreno y vegetación","Toda la vegetación y el terrain por igual","Únicamente el skybox y nubes","Solo el texto OSD, sin materiales del mundo"],"answer":0,"why":"El documento limita el efecto térmico a objetos y enemigos, no al terreno y vegetación.","id":"q057","link":"simdron/fpv-sensores.html"},{"doc":"simdron","page":115,"level":5,"topic":"Configuración del dron","question":"¿Qué control del panel altera la secuencia de inicio de motores?","options":["CSC","HOVER DRON","MODE","INIT Respawn"],"answer":0,"why":"La sección Dron describe un selector CSC de armado de motores.","id":"q058","link":"simdron/init-loadout.html"},{"doc":"simdron","page":117,"level":5,"topic":"Carga FPV","question":"¿Qué condición de plataforma impone el manual para activar un FPV Loadout?","options":["Dron FPV seleccionado","Dron RTF con Rack","Cualquier modelo con payload habilitado","Dron Mini con cámaras FLIR"],"answer":0,"why":"Aunque haya visualización en otros drones, la activación corresponde al FPV.","id":"q059","link":"simdron/init-loadout.html"},{"doc":"simdron","page":123,"level":5,"topic":"Auto Feedback","question":"¿En qué modo se utiliza específicamente el PID de altitud según el manual?","options":["HORIZON","ANGLE","ACRO","Todos por igual"],"answer":0,"why":"El panel Auto Feedback especifica estabilización de altura en HORIZON.","id":"q060","link":"simdron/auto-feedback.html"},{"doc":"simdron","page":124,"level":5,"topic":"Control PID","question":"Un dron oscila lentamente alrededor de la altitud objetivo tras subir I. ¿Qué sospechás?","options":["Ganancia integral excesiva","P de altitud demasiado alto","D de altitud excesivo","Dead Zone insuficiente"],"answer":0,"why":"El documento asocia demasiada integral con oscilación vertical lenta.","id":"q061","link":"simdron/auto-feedback.html"},{"doc":"simdron","page":135,"level":5,"topic":"Viento","question":"¿Qué valor permite fijar una dirección de viento no cardinal?","options":["Ángulo customizado de 0 a 360 grados","Selector cardinal Norte/Sur/Este/Oeste","Giro del gimbal entre 0 y 120°","Max Angle de los modos asistidos"],"answer":0,"why":"El panel Wind admite dirección personalizada por ángulo.","id":"q062","link":"simdron/wind.html"},{"doc":"simdron","page":142,"level":5,"topic":"Swarm","question":"¿Qué hace Path en el panel de enjambre?","options":["Activa una trayectoria para que los drones acompañen al principal","Invierte el orden de lanzamiento","Fija los drones a las mismas coordenadas sin seguimiento","Pausa la IA de las aeronaves secundarias"],"answer":0,"why":"Path habilita que el grupo siga al dron principal.","id":"q063","link":"simdron/ai.html"},{"doc":"simdron","page":146,"level":5,"topic":"Radio MEDEVAC","question":"En la línea de coordenadas de la radio 9-Line, ¿qué cambia la selección A/B?","options":["Precisión de seis u ocho dígitos MGRS","Precisión de cuatro u ocho dígitos MGRS","Precisión de seis o diez dígitos MGRS","Selección de canal de radio A o B"],"answer":0,"why":"A selecciona 6 dígitos y B 8 en la entrada de coordenadas.","id":"q064","link":"simdron/9-line-gps.html"},{"doc":"simdron","page":40,"level":4,"topic":"Interacción VR","question":"¿Qué método de movimiento de la guía requiere controladores Quest?","options":["Teleport","MGRS","FLIR","PID"],"answer":0,"why":"La sección de tipos de interacción indica que teleport se realiza con los controladores.","id":"q065","link":"simdron/teclado-vr.html"},{"doc":"simdron","page":55,"level":4,"topic":"Vuelo asistido","question":"¿Qué control se conserva como giro alrededor del eje vertical en HORIZON?","options":["Yaw","Roll","FOV","Drag"],"answer":0,"why":"Yaw continúa representando rotación sobre el eje vertical.","id":"q066","link":"simdron/modos-vuelo.html"},{"doc":"simdron","page":56,"level":4,"topic":"Modos de vuelo","question":"¿Qué característica tiene ANGLE que ACRO no impone?","options":["Límite de inclinación con autoestabilización","Vuelo libre ilimitado sin asistencia","Prohibición absoluta de yaw","Ausencia de throttle"],"answer":0,"why":"ANGLE limita inclinación y estabiliza; ACRO permite rotación libre.","id":"q067","link":"simdron/modos-vuelo.html"},{"doc":"simdron","page":58,"level":4,"topic":"Modelos de dron","question":"¿Qué modelo del manual se asemeja a un quad FPV competitivo de siete pulgadas?","options":["FPV","SRR","Mini","RTF"],"answer":0,"why":"El modelo FPV está descrito como 7 pulgadas y orientado a vuelo FPV.","id":"q068","link":"simdron/modelos-pid.html"},{"doc":"simdron","page":94,"level":4,"topic":"SRR","question":"¿Con qué dispositivo se controla manualmente el dron SRR según el manual?","options":["Teclado Bluetooth","Sensor de temperatura del visor","El mouse del instructor únicamente","Los botones de volumen del Quest"],"answer":0,"why":"El dron observador SRR admite operación mediante teclado Bluetooth.","id":"q069","link":"simdron/srr.html"},{"doc":"simdron","page":103,"level":4,"topic":"OSD","question":"¿Qué dato describe el ancho de encuadre de la cámara del dron?","options":["FOV","AGL","MSL","Drag"],"answer":0,"why":"FOV es el campo de visión de la cámara.","id":"q070","link":"simdron/osd.html"},{"doc":"simdron","page":105,"level":4,"topic":"OSD","question":"¿Con qué mecanismo se obtiene la distancia del telémetro a un objeto?","options":["Rayo sensor hacia una superficie con colisión","Lectura del micrófono del Quest","Estimación por número de FPS","Código de licencia del visor"],"answer":0,"why":"El telémetro calcula distancia métrica hasta terreno u objetos detectables por colisión.","id":"q071","link":"simdron/osd.html"},{"doc":"simdron","page":106,"level":4,"topic":"Degradación visual","question":"¿Qué modo superpone lluvia en lente e interferencia analógica?","options":["Combined","Clean","Only GPS","HORIZON"],"answer":0,"why":"Combined combina las dos capas de degradación visual descritas.","id":"q072","link":"simdron/capas-senal.html"},{"doc":"simdron","page":119,"level":4,"topic":"Rates","question":"¿Qué efecto tiene subir el límite Max Angle en modos asistidos?","options":["Permitir mayor inclinación y desplazamiento lateral","Reducir a cero el FOV","Bloquear todo el giro yaw","Duplicar la batería"],"answer":0,"why":"El capítulo de física indica mayor agilidad con límites angulares superiores.","id":"q073","link":"simdron/fisicas-presets.html"},{"doc":"simdron","page":126,"level":4,"topic":"Sistema de cámara","question":"¿Para qué sirve HDMI dentro del simulador según la guía?","options":["Reproducir la señal del dron en otras pantallas virtuales","Cambiar el firmware del visor","Grabar directamente la memoria del router","Activar los sticks Bluetooth"],"answer":0,"why":"El panel System permite mostrar video en pantallas dentro del entorno virtual.","id":"q074","link":"simdron/system.html"},{"doc":"simdron","page":141,"level":4,"topic":"Swarm","question":"¿Qué entrena el enjambre respecto al vuelo del alumno?","options":["Convivir con otras aeronaves y evitar colisiones","Configurar impresoras de red","Cambiar la cuenta de Meta","Eliminar los obstáculos del terreno"],"answer":0,"why":"El texto describe múltiples drones próximos que exigen atención espacial.","id":"q075","link":"simdron/ai.html"},{"doc":"simdron","page":149,"level":4,"topic":"ECM","question":"¿Qué subsistemas del dron puede degradar una contramedida simulada?","options":["Video y control de enlace","La contraseña de la cuenta Meta","El modelo 3D del controlador","El tamaño del archivo CSV"],"answer":0,"why":"La documentación de ECM describe interferencia de transmisión y mando.","id":"q076","link":"simdron/enemies-ecm.html"},{"doc":"simdron","page":169,"level":4,"topic":"Formación","question":"¿Qué se incorpora en la etapa 2 respecto a la anterior?","options":["Mapas, modelos, cámara, sensores y telemetría","Programación nativa de aplicaciones Android","Instalación de servidores Linux","Edición de hardware del Meta Quest"],"answer":0,"why":"La etapa 2 amplía exploración, observación y comprensión del entorno.","id":"q077","link":"simdron/etapas-formacion.html"},{"doc":"simdron","page":170,"level":4,"topic":"Formación","question":"¿Qué integra principalmente la etapa 3?","options":["Destreza, navegación, degradación y evaluación en misiones simuladas","Solo primeras nociones del visor","Únicamente cambio de strap","Solo emparejamiento Bluetooth"],"answer":0,"why":"La etapa 3 integra tareas complejas siempre como simulación educativa.","id":"q078","link":"simdron/etapas-formacion.html"},{"doc":"simdron","page":176,"level":4,"topic":"Planificación","question":"¿Cuántos módulos de una hora comprende el plan básico de 30 horas?","options":["Treinta","Diez","Quince","Sesenta"],"answer":0,"why":"Tres semanas de cinco días con dos módulos diarios suman 30 módulos.","id":"q079","link":"simdron/plan-30-horas.html"},{"doc":"simdron","page":45,"level":3,"topic":"Modo de sticks","question":"¿Cuántos esquemas de control de ejes emula el simulador?","options":["Cuatro","Dos","Seis","Dieciséis"],"answer":0,"why":"El manual muestra los modos de control 1, 2, 3 y 4.","id":"q080","link":"simdron/gamepad-hid.html"},{"doc":"simdron","page":38,"level":4,"topic":"Calidad gráfica","question":"¿Por qué existen varios perfiles de calidad en Quest?","options":["Para adaptar el coste gráfico al rendimiento disponible","Para cambiar el modo de radio del dron","Para activar la cuenta de Meta","Para escoger las coordenadas de un blanco"],"answer":0,"why":"Los presets gráficos ajustan sombras, detalle y otras cargas de renderizado.","id":"q081","link":"simdron/manual-y-calidad.html"},{"doc":"simdron","page":42,"level":4,"topic":"HID","question":"¿Por qué se eligió un gamepad estándar como entrada de vuelo?","options":["Por su disponibilidad, durabilidad y posibilidad de remapear ejes","Porque elimina la necesidad de configurar sticks","Porque garantiza control satelital real","Porque tiene GPS integrado"],"answer":0,"why":"El manual prioriza un HID común, reemplazable y configurable.","id":"q082","link":"simdron/gamepad-hid.html"},{"doc":"simdron","page":48,"level":4,"topic":"Diagnóstico HID","question":"¿Cómo se verifica si un botón o stick envía señal al juego?","options":["Observando los valores numéricos de sus axis al accionarlo","Tomando una foto con el dron","Midiendo la altura MSL","Activando tormentas eléctricas"],"answer":0,"why":"El panel muestra en tiempo real los valores individuales de los ejes.","id":"q083","link":"simdron/configurar-hid.html"},{"doc":"simdron","page":61,"level":4,"topic":"Preparación del vuelo","question":"¿Por qué el punto de despliegue puede estar en un espacio restringido?","options":["Para obligar a buscar mejor línea de visión y posición de lanzamiento","Para simular que no existen obstáculos","Para impedir cambiar el dron","Para representar una pista aeroportuaria siempre"],"answer":0,"why":"La escena común introduce restricciones espaciales y necesidad de evaluar LOS.","id":"q084","link":"simdron/primer-inicio.html"},{"doc":"simdron","page":65,"level":4,"topic":"Montaje inmersivo","question":"¿Qué sucede al finalizar la colocación de piezas según la interfaz de montaje?","options":["Se completa la secuencia conectando USB y luego RTx","Se publica un archivo CSV automáticamente","Se inicia un ataque virtual sin armado","Se cambian los permisos de Meta Quest"],"answer":0,"why":"La pantalla de montaje describe una secuencia de terminación con USB y RTx.","id":"q085","link":"simdron/adaptacion-montaje.html"},{"doc":"simdron","page":97,"level":4,"topic":"Navegación con teclado","question":"¿Cómo se selecciona el siguiente elemento del panel de UI con teclado?","options":["Tab","Ctrl + N","Alt + F4","Shift + F12"],"answer":0,"why":"Tab mueve el foco hacia el siguiente control interactivo.","id":"q086","link":"simdron/teclado-durante.html"},{"doc":"simdron","page":98,"level":4,"topic":"Movimiento en VR","question":"Si el avatar queda accidentalmente parcialmente bajo el suelo tras teleportarse, ¿qué control recomienda el manual?","options":["Botón A para saltar","Desactivar el antivirus","Subir el PID P","Cambiar el mapa MGRS"],"answer":0,"why":"La sección de locomoción recomienda saltar con A para corregir esa posición.","id":"q087","link":"simdron/teclado-durante.html"},{"doc":"simdron","page":127,"level":4,"topic":"Hardware","question":"¿Por qué el manual recomienda prudencia al usar luces del dron?","options":["Pueden incrementar el coste de recursos de renderizado","Desactivan los controladores Meta","Cambian el modo de licenciamiento","Eliminan el telemetro"],"answer":0,"why":"Las luces suman carga gráfica aunque mejoran el realismo.","id":"q088","link":"simdron/hardware.html"},{"doc":"simdron","page":129,"level":4,"topic":"Clima","question":"¿Por qué la lluvia ambiental se limita espacialmente en Quest?","options":["Para reducir carga de procesamiento y conservar rendimiento","Porque la lluvia solo existe en una textura estática","Porque el sistema no tiene efectos de gotas","Para desactivar las nubes"],"answer":0,"why":"El apartado Climatic explica que la lluvia no se procesa sobre todo el mapa por su coste.","id":"q089","link":"simdron/climatic.html"},{"doc":"simdron","page":130,"level":4,"topic":"Clima","question":"Si Rain está activado pero su intensidad se fija en cero, ¿qué se verá?","options":["Sin precipitación efectiva","Lluvia máxima","Tormenta eléctrica automática","Nieve constante"],"answer":0,"why":"Rain con intensidad cero equivale a lluvia nula.","id":"q090","link":"simdron/climatic.html"},{"doc":"simdron","page":156,"level":4,"topic":"Photo Manager","question":"¿Por qué el panel limita la cantidad de fotografías?","options":["Para simular una memoria de almacenamiento finita y fomentar selección","Porque Quest no admite imágenes","Para forzar siempre modo ACRO","Porque el instructor controla cada captura"],"answer":0,"why":"La limitación simula memoria SD y enseña criterio al tomar fotos.","id":"q091","link":"simdron/photo-manager.html"},{"doc":"simdron","page":167,"level":4,"topic":"Formación","question":"¿Por qué se recomienda progresión por etapas?","options":["Para dominar VR y control antes de situaciones complejas","Porque se debe comenzar siempre con máximo viento","Para evitar usar la navegación por coordenadas","Para impedir cualquier evaluación"],"answer":0,"why":"La planificación propone una curva gradual que reduce errores de iniciación.","id":"q092","link":"simdron/etapas-formacion.html"},{"doc":"simdron","page":99,"level":5,"topic":"Confort VR","question":"¿Cuál de estos factores puede aumentar la cinetosis en el simulador?","options":["Caídas de FPS durante movimiento inmersivo","Cambiar entre 2D y 3D con la cabeza quieta","Mantener vista fija de un panel sin locomoción","Apoyar el gamepad durante una pausa"],"answer":0,"why":"El manual enumera movimientos visuales y baja tasa de cuadros entre los desencadenantes.","id":"q093","link":"simdron/cinetosis.html"},{"doc":"simdron","page":150,"level":5,"topic":"FX","question":"¿Qué limitación operativa destaca el panel FX del visor?","options":["Solo un efecto activo a la vez","Hasta cinco efectos activos por ECM","Dos FX simultáneos si son one-shot","Cantidad ilimitada mientras el FPS sea estable"],"answer":0,"why":"El documento indica un efecto activo por vez en este panel.","id":"q094","link":"simdron/fx.html"},{"doc":"simdron","page":174,"level":5,"topic":"Autonomía","question":"Según las estimaciones de clase del manual, ¿cuánto dura Quest 3S con casting activo?","options":["Alrededor de 0,9 horas","Alrededor de 1,9 horas","Alrededor de 2,5 horas","Alrededor de 3,5 horas"],"answer":0,"why":"El apartado rendimiento estima 0,9 horas con casting y 1,9 sin él.","id":"q095","link":"simdron/aula-autonomia.html"},{"doc":"simdron","page":178,"level":5,"topic":"Planificación","question":"¿Qué contenidos corresponden al módulo 9 del plan básico?","options":["Coordenadas MGRS","Control del dron SRR","Lectura de Flight Log","Preflight Check-In"],"answer":0,"why":"El módulo 9 aborda grilla y precisión MGRS.","id":"q096","link":"simdron/plan-30-horas.html"},{"doc":"simdron","page":12,"level":3,"topic":"Cuidados del visor","question":"¿Cómo recomienda apoyar el visor mientras se carga?","options":["En posición normal sobre una superficie plana","Con las lentes contra la mesa","Colgado del cable USB-C","Inclinado con la batería hacia abajo"],"answer":0,"why":"El capítulo de cuidados indica apoyarlo normalmente sobre una superficie plana.","id":"q097","link":"simdron/quest-3s.html"},{"doc":"simdron","page":13,"level":3,"topic":"Transporte","question":"¿Cómo se recomienda transportar un kit Quest entre jornadas?","options":["Apagado y desconectado, en caja original o robustizada","Encendido para conservar la sincronización","Con los controles sueltos en una mochila sin protección","Con las cámaras destapadas y el cable tirante"],"answer":0,"why":"El capítulo de transporte indica apagar y desconectar los equipos y usar protección adecuada.","id":"q098","link":"simdron/quest-3s.html"},{"doc":"simdron","page":15,"level":4,"topic":"Autonomía","question":"Una clase prolongada incluye casting. ¿Qué accesorio recomienda el manual?","options":["Strap con al menos una batería extendida","Una antena RF externa","Un segundo gamepad para cada alumno","Un cable HDMI conectado al visor"],"answer":0,"why":"El manual aconseja una batería adicional cuando las sesiones son largas o incluyen casting.","id":"q099","link":"simdron/bateria.html"},{"doc":"simdron","page":17,"level":4,"topic":"Ergonomía","question":"Para un alumno nuevo en VR, ¿qué postura de inicio prioriza el manual?","options":["Sentado, con el frente despejado","Parado sobre una plataforma elevada","Caminando mientras mira el suelo","De espaldas al área de entrenamiento"],"answer":0,"why":"El capítulo de ergonomía prioriza una posición cómoda y un espacio frontal libre.","id":"q100","link":"simdron/ergonomia.html"},{"doc":"simdron","page":20,"level":4,"topic":"Interacción VR","question":"¿Qué sistema permite utilizar las manos como entrada sin sujetar controladores?","options":["Hand Tracking","GPS MGRS","RF Telemetry","Control PID de altitud"],"answer":0,"why":"Hand Tracking convierte gestos y posiciones detectadas por cámaras en entrada de usuario.","id":"q101","link":"simdron/controles-meta.html"},{"doc":"simdron","page":25,"level":4,"topic":"Transferencia de archivos","question":"Al conectar Quest por USB-C a una PC, ¿qué debe atender el alumno dentro del visor?","options":["La notificación para autorizar el acceso a archivos","La selección del modo ACRO","La calibración del viento","La activación de una misión aleatoria"],"answer":0,"why":"El capítulo de transferencia describe la notificación del sistema al conectar el visor.","id":"q102","link":"simdron/sistema-operativo.html"},{"doc":"simdron","page":26,"level":4,"topic":"Actualizaciones","question":"¿Qué dos actualizaciones distingue el manual para mantener operativo el kit?","options":["Meta Horizon OS y la aplicación SimDron","Unity Editor y SteamVR de la PC","El firmware del router y los mapas de Google únicamente","Los controladores gráficos de Windows y Unreal Engine"],"answer":0,"why":"La documentación diferencia la actualización del sistema y la de SimDron.","id":"q103","link":"simdron/sistema-operativo.html"},{"doc":"simdron","page":28,"level":4,"topic":"Seguridad VR","question":"¿Para qué sirven los límites espaciales del visor?","options":["Para definir un área segura y reducir golpes o tropiezos","Para restringir el máximo de AGL","Para limitar los drones de una misión","Para bloquear señales de radio externas"],"answer":0,"why":"El sistema de espacios detecta el entorno y permite definir límites de seguridad.","id":"q104","link":"simdron/sistema-operativo.html"},{"doc":"simdron","page":32,"level":4,"topic":"Casting","question":"Para transmitir del Quest a una tablet mediante Meta Horizon App, ¿qué condición de conectividad recomienda el manual?","options":["Que Quest y tablet estén conectados por Wi-Fi compatible","Conectar siempre el visor por HDMI a la tablet","Desactivar toda red en ambos dispositivos","Instalar Mission Control obligatoriamente"],"answer":0,"why":"La guía describe transmisión mediante Wi-Fi y Meta Horizon App.","id":"q105","link":"simdron/cuenta-chat-casting.html"},{"doc":"simdron","page":35,"level":4,"topic":"Captura y video","question":"¿Qué opciones agrupa el menú renovado de capturas del Quest?","options":["Capturas, grabación y transmisión","Únicamente ajuste de PID","Solo calibración del joystick","Solo compra de aplicaciones"],"answer":0,"why":"El manual enumera fotografía, grabación y casting/streaming en el sistema.","id":"q106","link":"simdron/nueva-interfaz.html"},{"doc":"simdron","page":36,"level":3,"topic":"Biblioteca de aplicaciones","question":"En la biblioteca renovada, ¿cómo se accede a opciones adicionales de una aplicación?","options":["Manteniendo presionado su icono","Moviendo el stick de throttle al máximo","Reiniciando el router","Pulsando Reset de físicas"],"answer":0,"why":"El manual explica el menú contextual mediante pulsación prolongada del icono.","id":"q107","link":"simdron/nueva-interfaz.html"},{"doc":"simdron","page":37,"level":3,"topic":"Manual en VR","question":"¿Cómo se accede al manual integrado desde SimDron?","options":["Desde el icono correspondiente de la pantalla principal","Solo desde un documento físico impreso","Desde el panel de ECM del dron","Desde la carpeta Windows de Mission Control"],"answer":0,"why":"La guía muestra el acceso a una escena de manual desde la pantalla principal.","id":"q108","link":"simdron/manual-y-calidad.html"},{"doc":"simdron","page":39,"level":4,"topic":"Teclado Bluetooth","question":"En el primer emparejamiento del teclado, ¿qué intervención puede pedir Horizon OS?","options":["Introducir un código desde el teclado","Reprogramar el ESP32","Desbloquear el PID de altitud","Cambiar el FOV a 120 grados"],"answer":0,"why":"El manual advierte que en la sincronización inicial puede solicitar un código.","id":"q109","link":"simdron/teclado-vr.html"},{"doc":"simdron","page":43,"level":3,"topic":"Accesorios HID","question":"¿Cómo se fijan los prolongadores impresos en 3D para los sticks?","options":["A presión, sin modificar el control","Con soldadura sobre el circuito","Por pegado permanente de los potenciómetros","Con un adaptador HDMI"],"answer":0,"why":"La guía describe piezas que se colocan a presión y no requieren pegamento.","id":"q110","link":"simdron/gamepad-hid.html"},{"doc":"simdron","page":44,"level":4,"topic":"HID Test","question":"¿Qué modalidad de vuelo utiliza el dron de prueba del panel HID?","options":["ACRO","Solo RTH","Solo vuelo autónomo SAR","Modo de cámara NIR"],"answer":0,"why":"El test HID permite apreciar el control directo de los ejes en ACRO.","id":"q111","link":"simdron/gamepad-hid.html"},{"doc":"simdron","page":46,"level":4,"topic":"Configuración HID","question":"Tras calibrar un gamepad, ¿hay que repetir todo al iniciar cada vez?","options":["No, los ajustes se guardan automáticamente","Sí, siempre desde cero","Solo si está conectado por USB-C","Sí, después de cada respawn del dron"],"answer":0,"why":"La escena de configuración cuenta con guardado automático.","id":"q112","link":"simdron/configurar-hid.html"},{"doc":"simdron","page":64,"level":4,"topic":"Montaje inmersivo","question":"¿Qué finalidad pedagógica tiene la escena de montaje?","options":["Familiarizar con interacciones VR y componentes antes de volar","Calibrar únicamente la brújula real","Sustituir la evaluación de instructor","Generar terrenos nuevos automáticamente"],"answer":0,"why":"El montaje es una etapa didáctica previa al pilotaje.","id":"q113","link":"simdron/adaptacion-montaje.html"},{"doc":"simdron","page":69,"level":4,"topic":"Escenarios nacionales","question":"¿Qué región argentina inspira el escenario Forest según el manual?","options":["Bosques tropicales del noreste","Altiplano árido de la Puna","Mar abierto de Patagonia","Glaciares antárticos"],"answer":0,"why":"La tabla de similitudes geográficas asocia Forest con bosques tropicales del noreste.","id":"q114","link":"simdron/catalogo-escenarios.html"},{"doc":"simdron","page":72,"level":4,"topic":"Entrenamiento en escenarios","question":"Para calibrar escalas con referencias métricas visibles y piso plano, ¿qué escenario conviene?","options":["Deck","Forest","Coast","Trench"],"answer":0,"why":"Deck está descrito como laboratorio de calibración con reglajes métricos.","id":"q115","link":"simdron/escenarios-basicos.html"},{"doc":"simdron","page":73,"level":4,"topic":"Entrenamiento en escenarios","question":"¿Qué escenario ofrece volúmenes geométricos urbanos simplificados sin distracción visual?","options":["Polygon","Mountain","AirBase","FOB"],"answer":0,"why":"Polygon se diseñó como entorno urbano esquemático para navegación espacial.","id":"q116","link":"simdron/escenarios-basicos.html"},{"doc":"simdron","page":74,"level":4,"topic":"Entrenamiento en escenarios","question":"Para practicar transición interior-exterior en un volumen cerrado, ¿qué mapa corresponde?","options":["Hangar","Coast","Mountain","Field"],"answer":0,"why":"Hangar permite entrenar maniobras interiores y transición hacia el exterior.","id":"q117","link":"simdron/escenarios-basicos.html"},{"doc":"simdron","page":76,"level":4,"topic":"Entrenamiento en escenarios","question":"¿Qué escenario combina campo abierto con franjas de árboles y arbustos para orientar el vuelo?","options":["Field","Polygon","Deck","Industrial"],"answer":0,"why":"Field añade referencias naturales sin saturar el espacio de vuelo.","id":"q118","link":"simdron/escenarios-basicos.html"},{"doc":"simdron","page":77,"level":4,"topic":"Entrenamiento en escenarios","question":"¿Qué escenario es idóneo para maniobras entre tubos, estructuras metálicas y pasarelas?","options":["Industrial","Deck","Desert","Field"],"answer":0,"why":"Industrial concentra obstáculos verticales y estructuras técnicas.","id":"q119","link":"simdron/escenarios-intermedios.html"},{"doc":"simdron","page":78,"level":4,"topic":"Entrenamiento en escenarios","question":"Para practicar paso por claros entre ramas con visibilidad restringida, ¿qué escenario elegirías?","options":["Forest","Deck","AirBase","Desert"],"answer":0,"why":"Forest presenta vegetación densa y claros irregulares.","id":"q120","link":"simdron/escenarios-intermedios.html"},{"doc":"simdron","page":79,"level":4,"topic":"Entrenamiento en escenarios","question":"Para practicar corredores urbanos, esquinas y terrazas, ¿qué escenario encaja mejor?","options":["Urban","Desert","Field","Deck"],"answer":0,"why":"Urban se estructura en calles y edificaciones con referencias de arquitectura.","id":"q121","link":"simdron/escenarios-intermedios.html"},{"doc":"simdron","page":96,"level":3,"topic":"Atajos de teclado","question":"Si querés volver al menú principal desde un escenario, ¿qué tecla indica el manual?","options":["L","N","F","P"],"answer":0,"why":"El listado de atajos asigna L al regreso a la escena principal.","id":"q122","link":"simdron/teclado-durante.html"},{"doc":"simdron","page":108,"level":4,"topic":"FPV","question":"¿Qué característica tiene la presentación OSD en el modo inmersivo FPV?","options":["Información reducida y pantalla de proporción 1:1","Siempre cuatro pantallas simultáneas","Una pantalla externa obligatoria","Únicamente información de la batería de la PC"],"answer":0,"why":"El manual describe vista FPV anclada a cabeza con OSD reducido.","id":"q123","link":"simdron/fpv-sensores.html"},{"doc":"simdron","page":113,"level":4,"topic":"Interfaz de configuración","question":"¿Dónde está ubicada la tableta de ajustes de los sistemas de vuelo?","options":["Debajo del controlador virtual y unida a él","Detrás del router físico","En la pantalla de Windows obligatoriamente","En la biblioteca de Meta Horizon"],"answer":0,"why":"La configuración se presenta en una tableta anclada bajo el controlador.","id":"q124","link":"simdron/introduccion-config.html"},{"doc":"simdron","page":125,"level":4,"topic":"Sistema de cámara","question":"¿Qué módulo agrupa estabilización, telemetría visual y tipos de cámara?","options":["System","Payload","Gates","Contactos"],"answer":0,"why":"System reúne controles de cámara y de presentación del OSD.","id":"q125","link":"simdron/system.html"},{"doc":"simdron","page":131,"level":4,"topic":"Clima","question":"¿Qué parámetro cambia la hora simulada y por tanto iluminación y HDRI del cielo?","options":["Hour","Drag","P Gain","Channel"],"answer":0,"why":"El selector Hour modifica la luminosidad ambiental y exposición de cielo.","id":"q126","link":"simdron/climatic.html"},{"doc":"simdron","page":136,"level":4,"topic":"Payload","question":"¿Cuántas cargas pueden estar activas simultáneamente en el sistema Payload descrito?","options":["Una","Cuatro","Diez","Ilimitadas"],"answer":0,"why":"El panel exige limpiar una carga antes de activar otra.","id":"q127","link":"simdron/payload.html"},{"doc":"simdron","page":140,"level":4,"topic":"Items","question":"¿Qué objeto permite guardar referencias de coordenadas como ayuda de campo?","options":["Radio GPS simulada","Control de calidad QA","Skybox","Filtro TV analógico"],"answer":0,"why":"El apartado Items menciona la radio para marcar coordenadas.","id":"q128","link":"simdron/general-items.html"},{"doc":"simdron","page":143,"level":4,"topic":"Misiones","question":"¿Qué intenta reducir el presentador aleatorio de misiones?","options":["La intervención necesaria del instructor en prácticas autogestionadas","El alcance máximo de RF","El tamaño del PDF","La calidad del cielo HDRI"],"answer":0,"why":"El presentador ofrece briefing y objetivos sin planificar cada ejercicio a mano.","id":"q129","link":"simdron/mission-presenter.html"},{"doc":"simdron","page":144,"level":4,"topic":"Misiones","question":"Antes de aceptar una misión, ¿qué conjunto puede revisar el alumno?","options":["Escenario, clima, hora, viento, tiempo y parámetros de vuelo","Solo el número de serie del visor","Únicamente temperatura de la GPU","Solo nombre de la red Wi-Fi"],"answer":0,"why":"La pantalla de briefing reúne condiciones y parámetros del ejercicio.","id":"q130","link":"simdron/mission-presenter.html"},{"doc":"simdron","page":147,"level":4,"topic":"GPS simulado","question":"¿Para qué sirve el historial de la radio GPS interna?","options":["Guardar coordenadas relevantes para una posterior consulta","Cambiar el firmware del Quest","Editar un PDF del manual","Controlar la temperatura real del equipo"],"answer":0,"why":"La radio permite marcar y recuperar referencias de posición.","id":"q131","link":"simdron/9-line-gps.html"},{"doc":"simdron","page":148,"level":4,"topic":"Enemigos simulados","question":"¿Qué caracteriza a algunos sistemas enemigos del panel Enemy?","options":["Tienen máquina de estados e IA para desplazarse en el mapa","Son únicamente iconos estáticos en la UI","Necesitan siempre conexión real a Internet","No interactúan con el terreno"],"answer":0,"why":"El manual describe entidades autónomas y distribución por el escenario.","id":"q132","link":"simdron/enemies-ecm.html"},{"doc":"simdron","page":154,"level":4,"topic":"Gates","question":"¿Cuánto mide cada puerta del entrenamiento de Gates según el manual?","options":["Dos por dos metros","Un metro por diez","Cinco por veinte","Diez por diez"],"answer":0,"why":"Las puertas verdes se describen con medida de 2 × 2 metros.","id":"q133","link":"simdron/gates.html"},{"doc":"simdron","page":164,"level":4,"topic":"Formación","question":"¿Qué habilidad adicional considera la formación además de pilotar?","options":["Lectura de telemetría, sensores y decisiones de misión","Solo velocidad de los sticks","Únicamente movimiento del joystick izquierdo","Solo cambiar el fondo del manual"],"answer":0,"why":"El capítulo formativo incluye interpretación, observación y criterios de misión.","id":"q134","link":"simdron/implementacion.html"},{"doc":"simdron","page":171,"level":4,"topic":"Diseño de aula","question":"¿Cuál es el equipamiento mínimo de un puesto standalone descrito?","options":["Quest, gamepad, controladores y teclado Bluetooth","Diez servidores dedicados","Pantalla 65 pulgadas obligatoria","Router de fibra óptica de alcance militar"],"answer":0,"why":"El aula mínima funciona autónomamente sin instructor PC ni router dedicado.","id":"q135","link":"simdron/aula-autonomia.html"},{"doc":"simdron","page":172,"level":4,"topic":"Diseño de aula","question":"¿Qué aporta una tablet y router a la configuración mínima?","options":["Casting y posibilidad de observación/asistencia","Sustituir completamente la aplicación de Quest","Cambiar el motor de físicas desde fuera","Eliminar la necesidad de un visor"],"answer":0,"why":"El diseño de aula 2 añade pantalla externa y red para asistencia.","id":"q136","link":"simdron/aula-autonomia.html"},{"doc":"simdron","page":177,"level":4,"topic":"Planificación","question":"¿Qué se trabaja al inicio del programa antes de pilotaje avanzado?","options":["Seguridad del aula y Meta Horizon OS","Solo vuelos con ECM máxima","Solo interceptores rápidos","Solo payload de fibra óptica"],"answer":0,"why":"Los primeros módulos cubren introducción al visor y sistema operativo.","id":"q137","link":"simdron/plan-30-horas.html"},{"doc":"simdron","page":179,"level":4,"topic":"Planificación","question":"¿Qué se evalúa al interpretar el Flight Log de un ejercicio?","options":["Duración, velocidad, coordenadas y métricas de vuelo","Solo la marca del gamepad","El número de imágenes del manual","La contraseña Wi-Fi"],"answer":0,"why":"El módulo de métricas enseña a interpretar resultados registrados.","id":"q138","link":"simdron/plan-30-horas.html"},{"doc":"simdron","page":180,"level":4,"topic":"Planificación","question":"¿Qué debe producir el módulo de misión de reconocimiento?","options":["Un reporte breve y ordenado","Un firmware nuevo","Una aplicación instalada en cada alumno","Un material de Blender"],"answer":0,"why":"La actividad de reconocimiento se vincula a documentación de observaciones.","id":"q139","link":"simdron/plan-30-horas.html"},{"doc":"simdron","page":183,"level":4,"topic":"Preflight","question":"¿Qué formato usa el Check-In de la escena de montaje?","options":["Preguntas de opción múltiple con validación y exportación","Solo examen oral sin guardar nada","Simulación de balística real","Gestor de correo electrónico"],"answer":0,"why":"La herramienta de Preflight genera preguntas aleatorias que pueden validarse y exportarse.","id":"q140","link":"simdron/preflight-debrief.html"},{"doc":"simdron","page":184,"level":4,"topic":"Debriefing","question":"¿Qué finalidad tiene el informe de Debriefing interno?","options":["Documentar y evaluar el ejercicio una vez concluido","Cambiar la licencia del Quest","Eliminar todas las métricas sin revisión","Actualizar el firmware del gamepad"],"answer":0,"why":"Debriefing cierra la estrategia educativa de simulación con un reporte posterior.","id":"q141","link":"simdron/preflight-debrief.html"},{"doc":"simdron","page":16,"level":3,"topic":"Arquitectura","question":"¿Qué significa que SimDron sea standalone en Quest?","options":["Se ejecuta en el propio visor sin depender de una PC","Exige una PC con Unity abierta","Solo puede iniciarse con cable USB","Funciona únicamente con conexión a Steam"],"answer":0,"why":"El programa reside y se ejecuta en el Quest con Meta Horizon OS.","id":"q142","link":"simdron/bateria.html"},{"doc":"simdron","page":18,"level":3,"topic":"Ergonomía","question":"¿Qué ajuste del visor debe adaptarse a la separación entre los ojos?","options":["Distancia interpupilar","Tasa de refresco de Mission Control","Frecuencia del Wi-Fi","Parámetro Drag del dron"],"answer":0,"why":"El ajuste de la distancia interpupilar ayuda a acomodar la visión al usuario.","id":"q143","link":"simdron/ergonomia.html"},{"doc":"simdron","page":19,"level":3,"topic":"Controles Quest","question":"¿Son imprescindibles los controladores Quest para todas las interacciones?","options":["No, algunas interacciones pueden hacerse con seguimiento de manos","Sí, incluso para cualquier gesto de pinch","No, porque SimDron no utiliza controles Quest","Solo si Mission Control está apagado"],"answer":0,"why":"El manual distingue funciones de controladores y acciones reemplazables mediante hand tracking.","id":"q144","link":"simdron/controles-meta.html"},{"doc":"simdron","page":23,"level":3,"topic":"Meta Horizon OS","question":"¿Cuál es el sistema operativo integrado en los visores del manual?","options":["Meta Horizon OS","Windows 11","SteamOS","Ubuntu Server"],"answer":0,"why":"Los Quest ejecutan Meta Horizon OS, con escritorio, aplicaciones y herramientas propias.","id":"q145","link":"simdron/sistema-operativo.html"},{"doc":"simdron","page":24,"level":3,"topic":"Meta Horizon OS","question":"¿Dónde se consultan controles como brillo, volumen y batería del visor?","options":["En el panel de configuración del sistema operativo","En el PID de rotación del dron","En la pestaña OPFOR/EW del instructor","En el formato de exportación CSV"],"answer":0,"why":"El panel de Horizon OS agrupa controles del propio dispositivo.","id":"q146","link":"simdron/sistema-operativo.html"},{"doc":"simdron","page":27,"level":3,"topic":"Meta Horizon OS","question":"¿Qué acción permite salir de la aplicación y acceder al sistema de Quest?","options":["Pulsar el botón Meta del controlador","Pulsar simultáneamente ambos gatillos de vuelo","Desactivar el router del aula","Cambiar el modo de vuelo a HORIZON"],"answer":0,"why":"El botón Meta abre la interfaz del sistema operativo desde la aplicación.","id":"q147","link":"simdron/sistema-operativo.html"},{"doc":"mission-control","page":12,"level":5,"topic":"Selección de aula","question":"Si una orden debe aplicarse solo al puesto Q03, ¿qué se configura antes?","options":["La estación Q03 en el contexto Aula","La opción TODOS del contexto Aula","La cámara FPV de Q03 en C2 Wall","El filtro de cartografía Q03"],"answer":0,"why":"El selector AULA/estación define a qué puesto se dirige una operación.","id":"q148","link":"mission-control/aula.html"},{"doc":"mission-control","page":31,"level":5,"topic":"Clases","question":"Después de cargar una planificación, ¿por qué se restaura primero localmente?","options":["Para que el instructor la revise antes de publicar","Para publicarla simultáneamente a todas las Quest","Para transformar la telemetría histórica en un preset","Para convertir automáticamente la clase en CSV"],"answer":0,"why":"CARGAR recupera el estado en PC antes de su utilización operativa.","id":"q149","link":"mission-control/clases.html"},{"doc":"mission-control","page":38,"level":5,"topic":"Dron Lab","question":"¿Qué ocurre con el preset local si el instructor aplica uno remoto?","options":["Se aplica en Quest sin sobrescribir permanentemente las preferencias locales","Se eliminan para siempre todas las preferencias del alumno","Solo cambia el PDF del manual","El Quest queda desconectado hasta reiniciar"],"answer":0,"why":"Los presets remotos no modifican de forma permanente el perfil del usuario.","id":"q150","link":"mission-control/dronlab.html"},{"doc":"mission-control","page":43,"level":5,"topic":"Dispositivos","question":"¿Por qué existe una ventana temporal de incorporación de hardware?","options":["Para evitar altas indefinidas de dispositivos no autorizados","Para conservar la lista de dispositivos por orden alfabético","Para evitar cambiar estaciones durante un ejercicio","Para limitar la cantidad de cámaras C2 Wall"],"answer":0,"why":"La incorporación de nuevos equipos se controla por una ventana temporal.","id":"q151","link":"mission-control/dispositivos.html"},{"doc":"mission-control","page":17,"level":4,"topic":"Mediciones","question":"¿Cómo se mide una distancia en Táctico?","options":["Marcando dos puntos del mapa con la herramienta de medir","Ingresando el nombre del alumno","Contando imágenes por segundo","Cambiando el zoom del Quest"],"answer":0,"why":"El módulo calcula en metros la distancia entre dos puntos marcados.","id":"q152","link":"mission-control/tactico.html"},{"doc":"mission-control","page":19,"level":4,"topic":"Contactos","question":"¿Qué ocurre al publicar contactos preparados en Mission Control?","options":["Se instancian en los Quest del aula correspondiente","Se crean archivos FBX en la notebook","Se reemplaza el terreno de todos los escenarios","Se envían automáticamente correos al instructor"],"answer":0,"why":"La publicación crea entidades de escenario en los simuladores conectados.","id":"q153","link":"mission-control/contactos.html"},{"doc":"mission-control","page":6,"level":5,"topic":"Arquitectura","question":"¿Qué ventaja operativa aporta que MC funcione como servicio de Windows?","options":["Separar el servidor de los clientes de interfaz","Ejecutar el backend sin depender de que una vista cliente esté abierta","Transmitir todo el video por HDMI en lugar de red","Sustituir el proceso de instalación Full"],"answer":0,"why":"La arquitectura de servicio permite un PC servidor con terminales adicionales.","id":"q154","link":"mission-control/instalacion.html"},{"doc":"mission-control","page":15,"level":5,"topic":"Táctico","question":"¿Qué muestra el botón Actualizar estado de Táctico en los Quest?","options":["Símbolos publicados en la pantalla virtual de 65 pulgadas","Los log de Firewall de Windows","Los ajustes de fábrica del visor","Las cámaras IR del router"],"answer":0,"why":"La actualización se refleja en la pantalla interactiva virtual del simulador.","id":"q155","link":"mission-control/tactico.html"},{"doc":"mission-control","page":34,"level":5,"topic":"OPFOR/EW","question":"¿Qué aporta OPFOR/EW al ejercicio?","options":["Oposición y degradación de señales para exigir adaptación del alumno","Símbolos solo en el mapa de la PC, sin publicar","Objetos físicos instanciados como Contactos","Un nuevo mapa GLB para todas las estaciones"],"answer":0,"why":"El módulo representa fuerza oponente y guerra electrónica simuladas.","id":"q156","link":"mission-control/opfor-ew.html"},{"doc":"mission-control","page":39,"level":5,"topic":"Auto/AI","question":"Para relevamiento sistemático del terreno, ¿qué modo de MC se describe?","options":["SURVEY","Solo incrementar el número de enemigos visibles, sin efectos de señal","Reemplazar el módulo Táctico por una cartografía diferente","Cambiar exclusivamente los iconos de la interfaz del Hub"],"answer":0,"why":"SURVEY propone un recorrido sistemático de relevamiento.","id":"q157","link":"mission-control/auto-ai.html"},{"doc":"mission-control","page":44,"level":5,"topic":"QA Aula","question":"¿Qué puerto TCP se menciona en el diagnóstico avanzado?","options":["8765","RECON","PROWL","SAR"],"answer":0,"why":"El manual lista TCP 8765 entre los datos de conectividad.","id":"q158","link":"mission-control/qa-aula.html"},{"doc":"mission-control","page":47,"level":5,"topic":"Mapas","question":"¿Qué formatos se citan para agregar mapas a MC además de los precargados?","options":["PNG y GLB","42100","42101","8766"],"answer":0,"why":"El manual acepta importar mapas en PNG y modelos 3D GLB.","id":"q159","link":"mission-control/config-mapas.html"},{"doc":"mission-control","page":13,"level":4,"topic":"Cartografía","question":"¿Qué opción conviene en un aula sin acceso externo a Internet?","options":["Solo offline o ahorro de datos","PNG y CSV","GLB y WAV","SIMMAP y MP4"],"answer":0,"why":"La opción offline prioriza recursos locales cuando no hay salida a Internet.","id":"q160","link":"mission-control/cartografia.html"},{"doc":"mission-control","page":54,"level":4,"topic":"C2","question":"¿Qué herramienta de C2 permite una captura rápida de pantalla?","options":["Snap","Aula","QA","Upgrade"],"answer":0,"why":"Snap ofrece una captura rápida sin herramienta externa.","id":"q161","link":"mission-control/c2.html"},{"doc":"mission-control","page":56,"level":4,"topic":"C2 Wall","question":"Al activar la vista SRR de Wall, ¿qué se puede supervisar?","options":["Los drones observadores SRR de los diez puestos","Solo el equipo del administrador de Windows","Únicamente el clima global","Exclusivamente el fondo de OpenStreetMap"],"answer":0,"why":"Wall permite alternar a las cámaras SRR de los Quest conectados.","id":"q162","link":"mission-control/c2.html"},{"doc":"mission-control","page":57,"level":4,"topic":"Video C2","question":"¿Cuál de estos gradientes térmicos puede seleccionarse en C2?","options":["Iron","JPEG","HORIZON","MGRS"],"answer":0,"why":"La lista de VFX incluye Iron y Rainbow, además de White/Black Hot.","id":"q163","link":"mission-control/vfx-c2.html"},{"doc":"mission-control","page":58,"level":4,"topic":"Tablet","question":"¿Qué ventaja tiene el modo Captura de Tablet frente a Live?","options":["Congelar una imagen estable para revisar","Hacer más rápida la física del Quest","Cambiar el joystick Mode 2","Desactivar todos los sensores FLIR"],"answer":0,"why":"La vista Captura evita movimiento continuo y sirve para observar detalles.","id":"q164","link":"mission-control/tablet.html"},{"doc":"mission-control","page":5,"level":4,"topic":"Topología","question":"¿Por qué se recomienda conectar el Hub al router mediante Ethernet?","options":["Para reducir latencia entre estación de instructor y red","Para impedir que las Quest utilicen Wi-Fi","Para eliminar el streaming de cámaras","Para sustituir el panel de telemetría"],"answer":0,"why":"El manual recomienda conexión por cable entre notebook y router para bajar latencia.","id":"q165","link":"mission-control/topologia.html"},{"doc":"mission-control","page":51,"level":4,"topic":"Misiones","question":"¿Qué ocurre con las capas gráficas de una misión generada automáticamente?","options":["Se generan y después pueden seguir editándose","Quedan bloqueadas para siempre","Se guardan exclusivamente como MP3","Solo funcionan sin Hub"],"answer":0,"why":"El generador crea capas editables junto con la misión.","id":"q166","link":"mission-control/misiones.html"},{"doc":"mission-control","page":35,"level":5,"topic":"OPFOR/EW","question":"Al modificar el alcance ECM desde MC, ¿qué particularidad sigue existiendo en cada Quest?","options":["Cada sistema ECM conserva su propia forma de lóbulo de acción","Todos los lóbulos se vuelven esféricos e idénticos","Solo queda activo el lóbulo con mayor alcance","Los cinco ECM pasan a ser exclusivamente marcadores gráficos"],"answer":0,"why":"El manual recuerda propiedades individuales de los lóbulos en cada instancia.","id":"q167","link":"mission-control/opfor-ew.html"},{"doc":"mission-control","page":36,"level":5,"topic":"FX","question":"¿Qué diferencia hay entre un looping persistente y un One Shot?","options":["Uno permanece/repite y el otro se dispara como evento puntual","Ambos requieren disparo manual para cada cuadro","One Shot nunca puede limpiarse después de ejecutarse","Looping solo cambia la posición del efecto sin repetirlo"],"answer":0,"why":"El módulo distingue efectos continuos de eventos disparados.","id":"q168","link":"mission-control/fx.html"},{"doc":"mission-control","page":49,"level":5,"topic":"Mapas","question":"En la vista 3D rotada, ¿qué control conviene usar para mantener coherencia con elementos gráficos?","options":["Slider de giro","Rotación libre con la mano sin compensación","Control de elevación del dron","Cambio automático de mapa 2D"],"answer":0,"why":"El capítulo advierte que rotar libremente puede desincronizar capas y propone giro mediante slider.","id":"q169","link":"mission-control/config-mapas.html"},{"doc":"mission-control","page":53,"level":5,"topic":"Expo","question":"¿Qué puede producir el muestreo de un vuelo de un dispositivo dentro de Expo?","options":["Rutas basadas en el patrón de vuelo observado","Un preset PID calculado por la cámara","Un mapa GIS offline generado por triangulación","La grabación de todas las cámaras al FPS del Quest"],"answer":0,"why":"El modo Expo admite samplear vuelos para producir trazas de demostración.","id":"q170","link":"mission-control/expo.html"},{"doc":"mission-control","page":4,"level":4,"topic":"Topología","question":"¿Qué dispositivo de red se muestra en la topología de aula recomendada?","options":["Router TP-Link AX1800","Switch HDMI de cuatro puertos","Modem 3G obligatorio","Antena parabólica real de seguimiento"],"answer":0,"why":"La topología ilustrada incluye un router TP-Link AX1800.","id":"q171","link":"mission-control/topologia.html"},{"doc":"mission-control","page":8,"level":4,"topic":"Barra superior","question":"¿Qué función tiene LIVE en la barra superior?","options":["Controlar el modo de publicación y operación en vivo","Aumentar automáticamente el FPS del Quest","Editar el modelo 3D del dron","Restablecer la licencia del usuario"],"answer":0,"why":"LIVE gobierna la publicación hacia el aula y dispositivos asociados.","id":"q172","link":"mission-control/barra-superior.html"},{"doc":"mission-control","page":9,"level":4,"topic":"Navegación","question":"¿Qué efecto tiene contraer la barra lateral izquierda?","options":["Priorizar iconos en lugar de etiquetas de texto","Desactivar el mapa por completo","Eliminar la telemetría histórica","Cambiar el modo C2 a Foco"],"answer":0,"why":"El panel izquierdo puede mostrarse extendido o resumido en iconos.","id":"q173","link":"mission-control/panel-izquierdo.html"},{"doc":"mission-control","page":10,"level":4,"topic":"Área central","question":"¿Qué puede ocupar la franja inferior de trabajo del mapa?","options":["Gráfico, timeline o información auxiliar","Únicamente la contraseña del Hub","El asistente de compra de hardware","Solo la cámara del casco"],"answer":0,"why":"La franja inferior cambia según el módulo y puede mostrar series y línea temporal.","id":"q174","link":"mission-control/mapa-central.html"},{"doc":"mission-control","page":11,"level":4,"topic":"Resumen docente","question":"¿Cuál de estas métricas aparece en el resumen por dron?","options":["Distancia, velocidad máxima y AGL máxima","Temperatura del CPU y marca de GPU","Número de dedos visibles en hand tracking","Cantidad de materiales de Blender"],"answer":0,"why":"El resumen de MC muestra métricas de vuelo por puesto o aeronave.","id":"q175","link":"mission-control/panel-derecho.html"},{"doc":"mission-control","page":18,"level":4,"topic":"Calcos","question":"¿Qué tarea es apropiada para Calcos y no exige crear un objeto táctico estructurado?","options":["Dibujar un corredor de búsqueda sobre el mapa","Cambiar la cuenta de Meta del alumno","Instalar un parche de Windows","Configurar la batería 6S de un dron"],"answer":0,"why":"Calcos es una capa gráfica libre para briefing y planificación.","id":"q176","link":"mission-control/calcos.html"},{"doc":"mission-control","page":20,"level":4,"topic":"Contactos","question":"¿Qué información adicional puede mostrarse al posicionar el cursor sobre un contacto destruido?","options":["Información del impacto/estado del contacto","El código fuente de Unity","La contraseña de la cuenta Meta","El número de serie del router"],"answer":0,"why":"La ficha de contactos puede presentar información contextual tras un impacto.","id":"q177","link":"mission-control/contactos.html"},{"doc":"mission-control","page":30,"level":4,"topic":"Escenarios","question":"¿Qué distingue a Escenarios frente a Contactos en MC?","options":["Gestiona infraestructura y elementos físicos del ambiente","Solo presenta entidades para identificación de blancos","Únicamente registra capturas de vídeo","No permite colocar objetos en el mapa"],"answer":0,"why":"Escenarios está orientado a elementos de infraestructura, separado conceptualmente de Contactos.","id":"q178","link":"mission-control/escenarios.html"},{"doc":"mission-control","page":32,"level":4,"topic":"Ambiente","question":"¿Qué acción envía las condiciones de clima y cielo actuales a los dispositivos?","options":["Aplicar a aula","Guardar Flight Log","Reset de HID","C2 Foco"],"answer":0,"why":"Aplicar a aula publica la configuración ambiental correspondiente.","id":"q179","link":"mission-control/ambiente.html"},{"doc":"mission-control","page":40,"level":4,"topic":"Dron Instructor","question":"¿Qué control asigna la guía al zoom/FOV del dron del instructor?","options":["LB/RB","Start/Select","D-Pad vertical","Botón Meta"],"answer":0,"why":"La sección de controles docente asigna zoom a LB/RB.","id":"q180","link":"mission-control/instructor.html"},{"doc":"mission-control","page":41,"level":4,"topic":"Pre-vuelo","question":"¿Qué aporta la vista en tercera persona de Aula de Pre-vuelo?","options":["Referencia de trayectoria y orientación espacial del dron","Desactivar todos los sensores del Quest","Una licencia independiente","Cambiar el terreno de todos los alumnos"],"answer":0,"why":"La vista externa es un apoyo pedagógico de posición y desplazamiento.","id":"q181","link":"mission-control/instructor.html"},{"doc":"mission-control","page":42,"level":4,"topic":"Mensajes","question":"¿Qué dato puede enviar el docente con Mensajes además de texto?","options":["Coordenadas seleccionadas desde el mapa","El instalador EXE del Hub","Un proyecto entero de Unity","El historial de licencias"],"answer":0,"why":"El módulo permite transmitir referencias de mapa y coordenadas.","id":"q182","link":"mission-control/mensajes.html"},{"doc":"mission-control","page":46,"level":4,"topic":"Upgrade","question":"¿Qué tipo de actualización soporta el panel Upgrade para terminales ESP?","options":["OTA A/B","CD-ROM","Bluetooth de audio solamente","Reinstalación de Windows en el visor"],"answer":0,"why":"El módulo Upgrade está destinado a OTA A/B de dispositivos ESP.","id":"q183","link":"mission-control/input-upgrade.html"},{"doc":"mission-control","page":50,"level":4,"topic":"Datos históricos","question":"¿Qué slider cambia la proporción de altura en una visualización tridimensional?","options":["Altura","Aula","Rain","Brightness"],"answer":0,"why":"El visor 3D dispone de control de altura de las trayectorias.","id":"q184","link":"mission-control/config-mapas.html"},{"doc":"mission-control","page":3,"level":3,"topic":"Aula híbrida","question":"¿Cuál es el papel de Mission Control respecto a SimDron VR?","options":["Coordinar dispositivos, telemetría y cámaras en un ejercicio de aula","Reemplazar el simulador de cada Quest","Fabricar drones físicos en tiempo real","Editar terrenos de Unity desde un navegador"],"answer":0,"why":"Mission Control actúa como Hub del aula, no como sustituto del simulador VR.","id":"q185","link":"mission-control/introduccion.html"},{"doc":"mission-control","page":7,"level":3,"topic":"Interfaz","question":"¿Cuántas zonas estables principales describe la interfaz de MC?","options":["Cuatro","Dos","Seis","Ocho"],"answer":0,"why":"La interfaz se organiza en barra superior, panel izquierdo, mapa central y panel derecho.","id":"q186","link":"mission-control/vista-general.html"},{"doc":"mission-control","page":16,"level":3,"topic":"Simbología","question":"¿Qué norma de referencia se cita para los símbolos tácticos?","options":["MIL-STD-2525D","USB 3.2","IEEE 802.11ax","MPEG-4"],"answer":0,"why":"El manual indica que el catálogo de símbolos se basa en MIL-STD-2525D.","id":"q187","link":"mission-control/tactico.html"},{"doc":"mission-control","page":37,"level":3,"topic":"Catálogo FX","question":"¿Cuál de estos nombres está listado en los efectos FX de MC?","options":["Rocket Trail","Meta Horizon Store","Waypoint Editor.exe","Controller Firmware"],"answer":0,"why":"La página de catálogo incluye Rocket Trail entre sus efectos.","id":"q188","link":"mission-control/fx.html"},{"doc":"mission-control","page":45,"level":3,"topic":"Input","question":"¿Para qué está destinado el panel Input experimental?","options":["Probar conexión de terminales ESP con gamepads remotos","Crear perfiles de color de impresoras","Editar vídeos institucionales","Agregar mapas de Google Earth directamente al Quest"],"answer":0,"why":"El panel Input se describe como prueba de terminales ESP.","id":"q189","link":"mission-control/input-upgrade.html"},{"doc":"mission-control","page":17,"level":5,"topic":"EW","question":"El lóbulo de EW dibujado en Táctico, ¿equivale automáticamente a cambiar los ECM activos del escenario?","options":["No; esa indicación gráfica no se sincroniza con los ECM simulados","Sustituye en forma permanente el perfil local del Quest","Solo cambia los controles visuales de Mission Control","Exige reinstalar la APK para restaurar el perfil anterior"],"answer":0,"why":"La anotación EW es visual; los sistemas ECM se manejan en OPFOR/EW.","id":"q190","link":"mission-control/tactico.html"},{"doc":"mission-control","page":31,"level":5,"topic":"Clases","question":"¿Qué tipo de datos no deberían estar dentro de una plantilla de clase guardada?","options":["Telemetría histórica y dispositivos conectados del momento","Sí, al dibujar el área se sincronizan las cinco ECM","Solo cuando el contacto se marca como Enemy","Sí, pero únicamente en el modo C2 Wall"],"answer":0,"why":"El guardado se orienta a planificación, no a estados efímeros de hardware y vuelo.","id":"q191","link":"mission-control/clases.html"},{"doc":"mission-control","page":19,"level":5,"topic":"Contactos","question":"¿Para qué existe el límite al publicar grandes cantidades de contactos?","options":["Para evitar sobrecargar el sistema con GameObjects","El conjunto de capas de planificación editables","La distribución de símbolos para briefing","El ambiente preparado para una clase recurrente"],"answer":0,"why":"El manual lo presenta como control defensivo de rendimiento.","id":"q192","link":"mission-control/contactos.html"},{"doc":"mission-control","page":17,"level":5,"topic":"Waypoints","question":"¿Qué acción publica en los Quest la ruta de waypoints creada en MC?","options":["Actualizar ruta","Para impedir más de diez clases guardadas","Para limitar la longitud de los archivos CSV","Para evitar un exceso de cambios de vista C2"],"answer":0,"why":"El instructor publica la traza mediante la opción de actualización de ruta.","id":"q193","link":"mission-control/tactico.html"},{"doc":"mission-control","page":6,"level":4,"topic":"Instalación","question":"¿Qué paquete se recomienda para una primera instalación de Mission Control?","options":["Full","Guardar clase","Actualizar estado de símbolos","Aplicar a aula desde Ambiente"],"answer":0,"why":"El instalador Full corresponde a la instalación inicial o cambios grandes.","id":"q194","link":"mission-control/instalacion.html"},{"doc":"mission-control","page":57,"level":4,"topic":"Video C2","question":"¿Dónde se aplican los cambios VFX de brillo, contraste y gradiente térmico?","options":["En la presentación de C2, no en la configuración propia de cada Quest","En los sensores reales del router","En el modo de radio del dron","En todos los Quest forzosamente"],"answer":0,"why":"El manual separa VFX de C2 de la visualización local del alumno.","id":"q195","link":"mission-control/vfx-c2.html"},{"doc":"mission-control","page":58,"level":4,"topic":"Tablet","question":"¿Qué frecuencia menciona el modo Live de Tablet para asistencia al alumno?","options":["Aproximadamente ocho FPS","Exactamente 72 FPS","Una imagen por minuto","240 FPS"],"answer":0,"why":"El modo Live de la tablet transmite a unos ocho cuadros por segundo.","id":"q196","link":"mission-control/tablet.html"},{"doc":"mission-control","page":39,"level":4,"topic":"Auto/AI","question":"¿Qué modo de AI mantiene una trayectoria circular alrededor de un punto?","options":["ORBIT","SURVEY","RTH","OFF"],"answer":0,"why":"ORBIT mantiene la órbita sobre un objetivo o punto indicado.","id":"q197","link":"mission-control/auto-ai.html"},{"doc":"mission-control","page":15,"level":4,"topic":"Táctico","question":"Para insertar un símbolo en Táctico, ¿qué secuencia describe el manual?","options":["Elegir símbolo y hacer clic en el mapa","Desconectar el Hub y reiniciar Windows","Abrir el PID y aumentar P","Crear un mapa GLB nuevo"],"answer":0,"why":"La sección Táctico añade simbología seleccionándola y posicionándola en el mapa.","id":"q198","link":"mission-control/tactico.html"},{"doc":"mission-control","page":44,"level":4,"topic":"QA Aula","question":"¿Dónde se guardan las capturas de soporte realizadas desde QA Aula?","options":["Imágenes/SimDron","Descargas/Steam","Documentos/UnityPackages","Windows/System32/Meta"],"answer":0,"why":"La sección indica un directorio de imágenes SimDron.","id":"q199","link":"mission-control/qa-aula.html"},{"doc":"mission-control","page":31,"level":4,"topic":"Clases","question":"¿Dónde se guardan las planificaciones de clases del instructor?","options":["En la PC/Hub local","En cada control DualSense","En el firmware del router","Solo en los cascos de todos los alumnos"],"answer":0,"why":"El capítulo describe persistencia local en el equipo instructor.","id":"q200","link":"mission-control/clases.html"}];
